-- Ladder step fixes (2026-11-18): the Challenge answer could be guessed from step answers (LADDER_RULES_v2 4.3).
-- Square Triples Step 2: 16 -> 10. Every Power of Two Step 3: 8 -> 12, Step 4: 8 -> 10. Challenges unchanged.
-- Source: olympiad/ladders/v2/LADDERS_v2_batch1.md and batch3.md (text generated by import_ladders_v2.build).
-- The answer line changes, so this cannot go through --update-text (it refuses answer changes on purpose).
-- Run in the Supabase SQL Editor after a backup. Run BEFORE import_ladders_v2.py --apply --update-text.
-- Each block stops with an error if the problem is not found exactly once or its answer is not the old one,
-- so running it twice is safe (the second run stops at the first block without changing anything).
BEGIN;

-- Square Triples — Step 2: 16 -> 10
DO $do$
DECLARE pid uuid; n int;
BEGIN
  SELECT count(*), min(id::text)::uuid INTO n, pid FROM public.problems WHERE title = $fix$Square Triples — Step 2$fix$;
  IF n <> 1 THEN RAISE EXCEPTION 'expected one problem titled %, found %', $fix$Square Triples — Step 2$fix$, n; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.solutions WHERE problem_id = pid AND split_part(content, E'\n', 1) = 'Answer: 16') THEN
    RAISE EXCEPTION 'answer of % is not the old value 16 (already fixed?)', $fix$Square Triples — Step 2$fix$;
  END IF;
  UPDATE public.problems SET content = $fix$Setup: A square triple is three different positive whole numbers x < y < z such that x + y, x + z and y + z are all perfect squares. For example 6, 19, 30 is a square triple: 25, 36 and 49 are squares.

Three numbers x < y < z satisfy x + y = 64, x + z = 100 and y + z = 144. What is x?

Answer with a single number, such as 42 or 3/8.$fix$, updated_at = now() WHERE id = pid;
  UPDATE public.solutions SET content = $fix$Answer: 10

X = (64 + 100 − 144)/2 = 10 (then y = 54 and z = 90).$fix$, updated_at = now() WHERE problem_id = pid;
END $do$;

-- Every Power of Two — Step 3: 8 -> 12
DO $do$
DECLARE pid uuid; n int;
BEGIN
  SELECT count(*), min(id::text)::uuid INTO n, pid FROM public.problems WHERE title = $fix$Every Power of Two — Step 3$fix$;
  IF n <> 1 THEN RAISE EXCEPTION 'expected one problem titled %, found %', $fix$Every Power of Two — Step 3$fix$, n; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.solutions WHERE problem_id = pid AND split_part(content, E'\n', 1) = 'Answer: 8') THEN
    RAISE EXCEPTION 'answer of % is not the old value 8 (already fixed?)', $fix$Every Power of Two — Step 3$fix$;
  END IF;
  UPDATE public.problems SET content = $fix$Setup: For a fraction x between 0 and 1, build a new decimal y: the n-th digit of y after the decimal point is the (2ⁿ)-th digit of x. (So y uses the 2nd, 4th, 8th, 16th, … digits of x.) A decimal eventually repeats with period p if, after some point, every digit equals the digit p places later; the period is the smallest such p.

What is the smallest k ≥ 1 with 2ᵏ leaving remainder 1 when divided by 13?

Answer with a single number, such as 42 or 3/8.$fix$, updated_at = now() WHERE id = pid;
  UPDATE public.solutions SET content = $fix$Answer: 12

2, 4, 8, 3, 6, 12, 11, 9, 5, 10, 7, 1 modulo 13: k = 12.$fix$, updated_at = now() WHERE problem_id = pid;
END $do$;

-- Every Power of Two — Step 4: 8 -> 10
DO $do$
DECLARE pid uuid; n int;
BEGIN
  SELECT count(*), min(id::text)::uuid INTO n, pid FROM public.problems WHERE title = $fix$Every Power of Two — Step 4$fix$;
  IF n <> 1 THEN RAISE EXCEPTION 'expected one problem titled %, found %', $fix$Every Power of Two — Step 4$fix$, n; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.solutions WHERE problem_id = pid AND split_part(content, E'\n', 1) = 'Answer: 8') THEN
    RAISE EXCEPTION 'answer of % is not the old value 8 (already fixed?)', $fix$Every Power of Two — Step 4$fix$;
  END IF;
  UPDATE public.problems SET content = $fix$Setup: For a fraction x between 0 and 1, build a new decimal y: the n-th digit of y after the decimal point is the (2ⁿ)-th digit of x. (So y uses the 2nd, 4th, 8th, 16th, … digits of x.) A decimal eventually repeats with period p if, after some point, every digit equals the digit p places later; the period is the smallest such p.

The digits of 1/23 repeat with period 22. What is the period of the remainders of 2, 4, 8, 16, … when divided by 22 (from the start)?

Answer with a single number, such as 42 or 3/8.$fix$, updated_at = now() WHERE id = pid;
  UPDATE public.solutions SET content = $fix$Answer: 10

2, 4, 8, 16, 10, 20, 18, 14, 6, 12, 2, … modulo 22: period 10 (22 = 2 × 11, and the order of 2 modulo 11 is 10).$fix$, updated_at = now() WHERE problem_id = pid;
END $do$;

COMMIT;

-- Check: the three answer lines
SELECT p.title, split_part(s.content, E'\n', 1) AS answer_line FROM public.problems p JOIN public.solutions s ON s.problem_id = p.id
WHERE p.title IN ('Square Triples — Step 2', 'Every Power of Two — Step 3', 'Every Power of Two — Step 4') ORDER BY p.title;
